    #[command(after_long_help = "\
Examples:
  toggl project list
  toggl project list --status active
  toggl project list --status archived
  toggl project list --status all
  toggl project list --json | jq '.[].name'")]
    List {
        #[arg(short, long, help = "Output in JSON format")]
        json: bool,
        #[arg(long, help = "Filter by status: active (default), archived, all")]
        status: Option<String>,
    },
    /// Create a new project in your workspace.
    Create {
        #[arg(help = "Name of the project to create")]
        name: String,
        #[arg(
            short,
            long,
            help = "Hex color for the project (e.g. #06aaf5)",
            default_value = "#06aaf5"
        )]
        color: String,
    },
    /// Rename a project in your workspace.
    Rename {
        #[arg(help = "Current name of the project")]
        old_name: String,
        #[arg(help = "New name for the project")]
        new_name: String,
    },
    /// Delete a project from your workspace by name.
    Delete {
        #[arg(help = "Name of the project to delete")]
        name: String,
    },
    /// Archive a project (sets active=false) without deleting it.
    Archive {
        #[arg(help = "Name of the project to archive")]
        name: String,
    },
    /// Unarchive a project (sets active=true).
    Unarchive {
        #[arg(help = "Name of the project to unarchive")]
        name: String,
    },
}

