use std::collections::BTreeMap;

use chrono::Datelike;

use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities::normalize_time_entry_list_filters;

/// Group billable, completed entries by the UTC calendar month of their start.
pub fn monthly_billable_seconds(
    entries: impl IntoIterator<Item = TimeEntry>,
) -> BTreeMap<String, i64> {
    let mut months = BTreeMap::new();

    for entry in entries {
        if !entry.billable || entry.stop.is_none() || entry.duration < 0 {
            continue;
        }

        let month = format!("{:04}-{:02}", entry.start.year(), entry.start.month());
        *months.entry(month).or_insert(0) += entry.duration;
    }

    months
}

pub struct InvoiceMonthlyCommand;

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let months = monthly_billable_seconds(entries);

        if months.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = months.values().sum();
        for (month, seconds) in months {
            println!("{month}  {seconds}s");
        }
        println!("Total  {total}s");
        Ok(())
    }
}

